{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_7c2b7a39d45e1e160fe20b29", "claim_ids": ["claim_9cf56842fbc120d4e2d9b2cd", "claim_c893e935c346b37711450224"], "query_ids": ["q_377"], "claims": [{"claim_id": "claim_9cf56842fbc120d4e2d9b2cd", "quote": "Covered products of China are generally subject to an additional 12.5% Section 301 duty under the forced-labor action effective July 24, 2026, unless a product exemption applies.", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "12.5%", "announcement_date": "July 24, 2026"}}, {"claim_id": "claim_c893e935c346b37711450224", "quote": "On July 23, 2026, USTR announced final action in Section 301 investigations concerning the failure of 60 economies to impose and effectively enforce prohibitions on imports produced with forced labor. Products of China are generally subject to an additional 12.5% Section 301 duty under this action, unless covered by an exemption.", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "legal_authority": "USTR", "duty_rate": "12.5%", "effective_date": "July 24, 2026"}}]}, {"pair_id": "conflict_8b63c3c1f67e60bcef4b9d5b", "claim_ids": ["claim_2cdb7fce00f997e6aa6f018a", "claim_dbcc08567604182eba96470d"], "query_ids": ["q_378"], "claims": [{"claim_id": "claim_2cdb7fce00f997e6aa6f018a", "quote": "The U.S. government currently levies a 38.4 percent tariff on Chinese EV batteries, with a 10 percent “baseline tariff” newly added in April.", "url": "https://www.koreajoongangdaily.com/business/exclusive-us-ev-battery-imports-from-korea-top-1300-as-tariffs-push-shift-from-china/11937242", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "U.S. government", "duty_rate": "38.4 percent", "effective_date": "April"}}, {"claim_id": "claim_dbcc08567604182eba96470d", "quote": "South Korea - January 2025: Battery imports from South Korea are subject to a 25% tariff, affecting energy storage systems and electric vehicle batteries.", "url": "https://manlybattery.com/battery-tools-and-resources/usa-import-duty-calculator", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "January 2025"}}]}, {"pair_id": "conflict_c235c62e604c94d9bf05e9e8", "claim_ids": ["claim_a7e9cd574dd1880ab3fdc992", "claim_ac3085e5fa39afdd634a0a36"], "query_ids": ["q_378"], "claims": [{"claim_id": "claim_a7e9cd574dd1880ab3fdc992", "quote": "Korean products, which enjoyed a zero percent tariff for decades under the Korea-U.S. FTA, are now subject to a 15 percent tariff.", "url": "https://www.koreajoongangdaily.com/business/exclusive-us-ev-battery-imports-from-korea-top-1300-as-tariffs-push-shift-from-china/11937242", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Korea-U.S. FTA", "duty_rate": "15 percent"}}, {"claim_id": "claim_ac3085e5fa39afdd634a0a36", "quote": "And US companies now have to pay a 15% tax on those batteries, where previously they didn't.", "url": "https://www.reddit.com/r/electricvehicles/comments/1mp1jzn/exclusive_us_ev_battery_imports_from_korea_top", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "US companies", "duty_rate": "15%", "effective_date": "now"}}]}, {"pair_id": "conflict_a0370b1759f8978750d44162", "claim_ids": ["claim_26c6882f7083e8034372ad81", "claim_c213ed65262e143a4423ce0c"], "query_ids": ["q_379"], "claims": [{"claim_id": "claim_26c6882f7083e8034372ad81", "quote": "February 2025: A 24% tariff is applied to battery products imported from Japan. These tariffs impact products used in automotive manufacturing and energy storage systems.", "url": "https://manlybattery.com/battery-tools-and-resources/usa-import-duty-calculator", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "24%", "effective_date": "February 2025"}}, {"claim_id": "claim_c213ed65262e143a4423ce0c", "quote": "South Korea and Japan, as major battery manufacturers, now sit in the forced-labor tariff's 10% tier", "url": "https://www.tariffstool.com/tariffs-on-energy-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Japan", "duty_rate": "10%"}}]}, {"pair_id": "conflict_8634d999c45f2b9894d36e0d", "claim_ids": ["claim_026c49a30f22ecabd38d0c74", "claim_5c055a95028b50fad3f515cc"], "query_ids": ["q_380"], "claims": [{"claim_id": "claim_026c49a30f22ecabd38d0c74", "quote": "We expect the Commission to place provisional duties on Chinese EV imports by early July.", "url": "https://rhg.com/research/aint-no-duty-high-enough", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "provisional duties", "affected_product": "Chinese EV imports", "announcement_date": "early July"}}, {"claim_id": "claim_5c055a95028b50fad3f515cc", "quote": "Should it determine that China-based producers have benefited from subsidies in ways that harm EU-based manufacturers, it could place provisional countervailing duties on China-origin EV imports anytime from now until July 3, and final duties by early November.", "url": "https://rhg.com/research/aint-no-duty-high-enough", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "provisional countervailing duties", "effective_date": "anytime from now until July 3"}}]}, {"pair_id": "conflict_ab73194a2e6e4232e55754d8", "claim_ids": ["claim_4e65ff315fdff7255fd0d4cd", "claim_e3c7338c0337e4a1c68f4cb5"], "query_ids": ["q_381"], "claims": [{"claim_id": "claim_4e65ff31